begin;
alter table public.products
  add column if not exists name_en text check (char_length(name_en) <= 80),
  add column if not exists name_de text check (char_length(name_de) <= 80),
  add column if not exists description_en text check (char_length(description_en) <= 140),
  add column if not exists description_de text check (char_length(description_de) <= 140);
alter table public.categories
  add column if not exists name_en text check (char_length(name_en) <= 40),
  add column if not exists name_de text check (char_length(name_de) <= 40);

-- Backfill only known source text, preserving any existing translations.
update public.products set name_en = coalesce(name_en, 'Turkish Coffee'), name_de = coalesce(name_de, 'Türkischer Kaffee'), description_en = case when description = 'Közde, bakır cezvede. Yanında lokum ve bir bardak su.' then coalesce(description_en, 'Brewed over embers in a copper pot. Served with Turkish delight and a glass of water.') else description_en end, description_de = case when description = 'Közde, bakır cezvede. Yanında lokum ve bir bardak su.' then coalesce(description_de, 'Über Glut in einer Kupferkanne zubereitet. Dazu Lokum und ein Glas Wasser.') else description_de end where name = 'Türk Kahvesi';
update public.products set name_en = coalesce(name_en, 'Filter Coffee'), name_de = coalesce(name_de, 'Filterkaffee'), description_en = case when description = 'Haftanın çekirdeği Etiyopya Guji — çiçeksi, hafif, berrak.' then coalesce(description_en, 'This week’s beans: Ethiopia Guji — floral, light and clean.') else description_en end, description_de = case when description = 'Haftanın çekirdeği Etiyopya Guji — çiçeksi, hafif, berrak.' then coalesce(description_de, 'Unsere Bohnen der Woche: Äthiopien Guji — blumig, leicht und klar.') else description_de end where name = 'Filtre Kahve';
update public.products set name_en = coalesce(name_en, 'Latte'), name_de = coalesce(name_de, 'Caffè Latte'), description_en = case when description = 'Çift shot espresso, ipeksi süt köpüğü. Yulaf sütüyle de olur.' then coalesce(description_en, 'Double espresso with silky milk foam. Also available with oat milk.') else description_en end, description_de = case when description = 'Çift shot espresso, ipeksi süt köpüğü. Yulaf sütüyle de olur.' then coalesce(description_de, 'Doppelter Espresso mit seidigem Milchschaum. Auch mit Hafermilch erhältlich.') else description_de end where name = 'Latte';
update public.products set name_en = coalesce(name_en, 'Salep'), name_de = coalesce(name_de, 'Salep'), description_en = case when description = 'Maraş sahlebi, üstüne bolca tarçın.' then coalesce(description_en, 'Traditional Maraş salep, generously topped with cinnamon.') else description_en end, description_de = case when description = 'Maraş sahlebi, üstüne bolca tarçın.' then coalesce(description_de, 'Traditioneller Salep aus Maraş, mit reichlich Zimt bestreut.') else description_de end where name = 'Sahlep';
update public.products set name_en = coalesce(name_en, 'Pot of Turkish Tea'), name_de = coalesce(name_de, 'Kännchen türkischer Tee'), description_en = case when description = 'İki kişilik, Rize çayı, ince belli bardakta.' then coalesce(description_en, 'Rize tea for two, served in traditional tulip-shaped glasses.') else description_en end, description_de = case when description = 'İki kişilik, Rize çayı, ince belli bardakta.' then coalesce(description_de, 'Rize-Tee für zwei, serviert in traditionellen tulpenförmigen Gläsern.') else description_de end where name = 'Demlik Çay';
update public.products set name_en = coalesce(name_en, 'Homemade Lemonade'), name_de = coalesce(name_de, 'Hausgemachte Limonade'), description_en = case when description = 'Taze sıkım, naneli, az şekerli.' then coalesce(description_en, 'Freshly squeezed, with mint and just a little sugar.') else description_en end, description_de = case when description = 'Taze sıkım, naneli, az şekerli.' then coalesce(description_de, 'Frisch gepresst, mit Minze und wenig Zucker.') else description_de end where name = 'Ev Yapımı Limonata';
update public.products set name_en = coalesce(name_en, 'Cold Brew'), name_de = coalesce(name_de, 'Cold Brew'), description_en = case when description = '18 saat soğuk demleme, buz üstünde.' then coalesce(description_en, 'Cold-steeped for 18 hours, served over ice.') else description_en end, description_de = case when description = '18 saat soğuk demleme, buz üstünde.' then coalesce(description_de, '18 Stunden kalt extrahiert, auf Eis serviert.') else description_de end where name = 'Cold Brew';
update public.products set name_en = coalesce(name_en, 'Iced Latte'), name_de = coalesce(name_de, 'Iced Latte'), description_en = case when description = 'Espresso, soğuk süt, bol buz.' then coalesce(description_en, 'Espresso, cold milk and plenty of ice.') else description_en end, description_de = case when description = 'Espresso, soğuk süt, bol buz.' then coalesce(description_de, 'Espresso, kalte Milch und viel Eis.') else description_de end where name = 'Buzlu Latte';
update public.products set name_en = coalesce(name_en, 'Cornelian Cherry Sherbet'), name_de = coalesce(name_de, 'Kornelkirsch-Scherbet'), description_en = case when description = 'Annemin tarifi, karanfilli.' then coalesce(description_en, 'My mother’s recipe, delicately spiced with cloves.') else description_en end, description_de = case when description = 'Annemin tarifi, karanfilli.' then coalesce(description_de, 'Nach dem Rezept meiner Mutter, mit Gewürznelken verfeinert.') else description_de end where name = 'Kızılcık Şerbeti';
update public.products set name_en = coalesce(name_en, 'San Sebastian Cheesecake'), name_de = coalesce(name_de, 'San-Sebastián-Cheesecake'), description_en = case when description = 'Yüksek ısıda pişen, yüzeyi karamelleşmiş, içi kremamsı Bask usulü cheesecake.' then coalesce(description_en, 'Basque-style cheesecake, baked at high heat with a caramelised top and a creamy centre.') else description_en end, description_de = case when description = 'Yüksek ısıda pişen, yüzeyi karamelleşmiş, içi kremamsı Bask usulü cheesecake.' then coalesce(description_de, 'Baskischer Cheesecake, bei hoher Hitze gebacken, mit karamellisierter Oberfläche und cremigem Kern.') else description_de end where name = 'San Sebastian Cheesecake';
update public.products set name_en = coalesce(name_en, 'Pistachio Brownie'), name_de = coalesce(name_de, 'Pistazien-Brownie'), description_en = case when description = 'Bitter çikolata, Antep fıstığı.' then coalesce(description_en, 'Dark chocolate and Antep pistachios.') else description_en end, description_de = case when description = 'Bitter çikolata, Antep fıstığı.' then coalesce(description_de, 'Dunkle Schokolade und Antep-Pistazien.') else description_de end where name = 'Fıstıklı Brownie';
update public.products set name_en = coalesce(name_en, 'Carrot & Cinnamon Cake'), name_de = coalesce(name_de, 'Karotten-Zimt-Kuchen'), description_en = case when description = 'Cevizli, krem peynir kaplamalı.' then coalesce(description_en, 'With walnuts and cream cheese frosting.') else description_en end, description_de = case when description = 'Cevizli, krem peynir kaplamalı.' then coalesce(description_de, 'Mit Walnüssen und Frischkäseglasur.') else description_de end where name = 'Havuçlu Tarçınlı Kek';
update public.products set name_en = coalesce(name_en, 'Kaşar Cheese Toast'), name_de = coalesce(name_de, 'Toast mit Kaşar-Käse'), description_en = case when description = 'Ekşi maya ekmek, eski kaşar, tereyağı.' then coalesce(description_en, 'Sourdough bread, aged kaşar cheese and butter.') else description_en end, description_de = case when description = 'Ekşi maya ekmek, eski kaşar, tereyağı.' then coalesce(description_de, 'Sauerteigbrot, gereifter Kaşar-Käse und Butter.') else description_de end where name = 'Kaşarlı Tost';
update public.products set name_en = coalesce(name_en, 'Spicy Sucuk Toast'), name_de = coalesce(name_de, 'Scharfer Sucuk-Toast'), description_en = case when description = 'Kasap sucuğu, kaşar, pul biber.' then coalesce(description_en, 'Butcher’s sucuk sausage, kaşar cheese and chilli flakes.') else description_en end, description_de = case when description = 'Kasap sucuğu, kaşar, pul biber.' then coalesce(description_de, 'Sucuk vom Metzger, Kaşar-Käse und Chiliflocken.') else description_de end where name = 'Acılı Sucuklu Tost';
update public.products set name_en = coalesce(name_en, 'Hummus Plate'), name_de = coalesce(name_de, 'Hummus-Teller'), description_en = case when description = 'Zeytinyağı, sumak, köz biber, pide.' then coalesce(description_en, 'Olive oil, sumac, roasted peppers and pide bread.') else description_en end, description_de = case when description = 'Zeytinyağı, sumak, köz biber, pide.' then coalesce(description_de, 'Olivenöl, Sumach, geröstete Paprika und Pide-Brot.') else description_de end where name = 'Humus Tabağı';
update public.products set name_en = coalesce(name_en, 'Menemen'), name_de = coalesce(name_de, 'Menemen'), description_en = case when description = 'Köy yumurtası, közlenmiş biber, ekşi maya ekmekle.' then coalesce(description_en, 'Village eggs and roasted peppers, served with sourdough bread.') else description_en end, description_de = case when description = 'Köy yumurtası, közlenmiş biber, ekşi maya ekmekle.' then coalesce(description_de, 'Landeier und geröstete Paprika, serviert mit Sauerteigbrot.') else description_de end where name = 'Menemen';
update public.categories set name_en = coalesce(name_en, 'Hot Drinks'), name_de = coalesce(name_de, 'Heiße Getränke') where name = 'Sıcak İçecekler';
update public.categories set name_en = coalesce(name_en, 'Cold Drinks'), name_de = coalesce(name_de, 'Kalte Getränke') where name = 'Soğuk İçecekler';
update public.categories set name_en = coalesce(name_en, 'Sweets'), name_de = coalesce(name_de, 'Süßspeisen') where name = 'Tatlılar';
update public.categories set name_en = coalesce(name_en, 'Snacks'), name_de = coalesce(name_de, 'Snacks') where name = 'Atıştırmalıklar';
update public.categories set name_en = coalesce(name_en, 'Breakfast'), name_de = coalesce(name_de, 'Frühstück') where name = 'Kahvaltılık';
notify pgrst, 'reload schema';
commit;
select count(*) as translated_products from public.products where name_en is not null and name_de is not null;
